<?php require __DIR__.'/../vendor/autoload.php'; $pdo=new PDO('mysql:host='.($_ENV['DB_HOST']??'mysql').';dbname='.($_ENV['DB_DATABASE']??'lab5'),$_ENV['DB_USERNAME']??'lab5',$_ENV['DB_PASSWORD']??'lab5_dev',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH); if($path==='/health'||isset($_GET['health'])){header('Content-Type: application/json'); echo json_encode(['status'=>'ok']); exit;} $pdo->exec(file_get_contents(__DIR__.'/../database/schema.sql')); header('Content-Type: application/json'); try { if($path==='/api/tasks'&&$_SERVER['REQUEST_METHOD']==='GET'){ $s=new App\Services\TaskService($pdo); echo json_encode($s->listOpen((int)($_GET['customer']??1))); exit;} if(preg_match('#^/api/tasks/(\d+)/complete$#',$path,$m)&&$_SERVER['REQUEST_METHOD']==='POST'){ $s=new App\Services\TaskService($pdo); echo json_encode($s->complete((int)$m[1],(int)($_GET['customer']??1))); exit;} http_response_code(404); echo json_encode(['error'=>'not found']); } catch(Throwable $e){http_response_code($e->getMessage()==='Forbidden'?403:422); echo json_encode(['error'=>$e->getMessage()]);}
